<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3'; import { computed, ref } from 'vue'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input';
const props=defineProps<{groups:any[];people:any[];laborMethods:any[];periods:any[];now:string;canPlan:boolean}>();const selectedGroup=ref(props.groups[0]?.recipe_version_id??'');const group=computed(()=>props.groups.find(g=>g.recipe_version_id===selectedGroup.value));const form=useForm({demand_ids:group.value?.demands.map((d:any)=>d.id)??[],planned_for:props.now,flour_quantity:null as number|null,labor_method:'standard_per_kg',responsible_person_id:props.people[0]?.id??''});const choose=(id:string)=>{selectedGroup.value=id;form.demand_ids=group.value?.demands.map((d:any)=>d.id)??[];form.flour_quantity=null};const selected=computed(()=>group.value?.demands.filter((d:any)=>form.demand_ids.includes(d.id))??[]);const suggested=computed(()=>selected.value.reduce((s:number,d:any)=>s+Number(d.flour),0));const period=computed(()=>{const d=new Date(form.planned_for);return props.periods.find(p=>p.year===d.getFullYear()&&p.month===d.getMonth()+1)});
</script>
<template><Head title="Demanda pendiente"/><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header class="flex justify-between"><div><h1 class="text-2xl font-semibold">Demanda pendiente</h1><p class="text-sm text-muted-foreground">Pedidos agrupados por masa con harina sugerida.</p></div><Button variant="outline" as-child><Link href="/orders">Pedidos</Link></Button></header><div v-if="groups.length" class="grid gap-5 lg:grid-cols-[18rem_1fr]"><aside class="grid content-start gap-2"><button v-for="g in groups" :key="g.recipe_version_id" class="rounded-lg border p-3 text-left" :class="selectedGroup===g.recipe_version_id?'border-primary bg-muted/40':''" @click="choose(g.recipe_version_id)"><strong class="text-sm">{{g.recipe}}</strong><p class="text-xs text-muted-foreground">{{Number(g.suggested_flour).toFixed(3)}} kg harina · {{g.demands.length}} pedidos</p></button></aside><section class="grid gap-4"><div class="overflow-x-auto rounded-xl border bg-card"><table class="w-full text-sm"><thead class="border-b bg-muted/40 text-left"><tr><th class="px-4 py-3"></th><th class="px-4 py-3">Pedido</th><th class="px-4 py-3">Producto</th><th class="px-4 py-3">Faltante</th><th class="px-4 py-3">Masa / harina</th></tr></thead><tbody class="divide-y"><tr v-for="d in group?.demands" :key="d.id"><td class="px-4 py-3"><input v-model="form.demand_ids" type="checkbox" :value="d.id"/></td><td class="px-4 py-3">{{d.order}}<small class="block text-muted-foreground">{{d.customer}} · {{d.due_at}}</small></td><td class="px-4 py-3">{{d.product}}</td><td class="px-4 py-3">{{d.quantity}}</td><td class="px-4 py-3">{{d.dough}} kg / {{d.flour}} kg</td></tr></tbody></table></div><form v-if="canPlan" class="grid gap-4 rounded-xl border bg-card p-5 md:grid-cols-2" @submit.prevent="form.post('/orders/demand/production')"><div class="grid gap-2"><label class="text-sm font-medium">Fecha planeada</label><Input v-model="form.planned_for" type="datetime-local"/></div><div class="grid gap-2"><label class="text-sm font-medium">Harina manual opcional</label><Input v-model.number="form.flour_quantity" type="number" min="0.000001" step="0.000001" :placeholder="`Sugerida ${suggested.toFixed(3)} kg`"/></div><div class="grid gap-2"><label class="text-sm font-medium">Responsable</label><select v-model="form.responsible_person_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="p in people" :key="p.id" :value="p.id">{{p.name}}</option></select></div><div class="grid gap-2"><label class="text-sm font-medium">Mano de obra</label><select v-model="form.labor_method" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="m in laborMethods" :key="m.value" :value="m.value">{{m.label}}</option></select></div><p class="text-sm">Seleccionados: {{selected.length}} · harina sugerida <strong>{{suggested.toFixed(3)}} kg</strong> · periodo {{period?'abierto':'faltante'}}</p><Button type="submit" :disabled="form.processing||!form.demand_ids.length||!period">Crear producción consolidada</Button></form></section></div><p v-else class="rounded-xl border p-10 text-center text-sm text-muted-foreground">No hay productos pendientes de producción.</p></main></template>
